create table if not exists public.quran_settings(id bigint primary key default 1 check(id=1),reader_id text,reader_name text,surah_number int not null default 1 check(surah_number between 1 and 114),audio_url text,autoplay boolean not null default false,updated_at timestamptz not null default now());
insert into public.quran_settings(id) values(1) on conflict do nothing;
create table if not exists public.app_artifacts(id bigint generated by default as identity primary key,version text not null,download_url text not null,release_notes text,created_at timestamptz not null default now());
alter table public.quran_settings enable row level security;alter table public.app_artifacts enable row level security;
create policy "public read quran" on public.quran_settings for select using(true);create policy "authenticated write quran" on public.quran_settings for all to authenticated using(true) with check(true);
create policy "public read artifacts" on public.app_artifacts for select using(true);create policy "authenticated write artifacts" on public.app_artifacts for all to authenticated using(true) with check(true);
alter publication supabase_realtime add table public.quran_settings;alter publication supabase_realtime add table public.app_artifacts;